//! `ios-bridge`: C interface over `parser-core` for the iPad app (`LocalParser`, stage I9).
//!
//! `crate-type = ["staticlib"]`, no Tokio/Axum/networking — just `parser-core` as a library.
//! Builds for `aarch64-apple-ios` (device) and `aarch64-apple-ios-sim` (Apple Silicon
//! simulator); packaged into an `.xcframework` by `build-xcframework.sh`, header generated by
//! `cbindgen`.
//!
//! Panics must not abort: `parser-core::parse_bytes` already catches panics from the
//! demoparser2 core with `catch_unwind`, and every exported function here wraps its body in
//! another `catch_unwind` so nothing unwinds across the C boundary. This crate (and anything
//! that embeds it) must not be built with `panic = "abort"`, or `catch_unwind` cannot work.

use std::cell::RefCell;
use std::ffi::{c_char, c_void, CStr, CString};
use std::fs::File;
use std::io::BufWriter;
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::path::Path;

use flate2::write::GzEncoder;
use flate2::Compression;
use parser_core::{Progress, Stage};

thread_local! {
    static LAST_ERROR: RefCell<Option<CString>> = const { RefCell::new(None) };
}

fn set_last_error(message: String) {
    // A NUL byte inside the message can't happen here (error text and paths from our own
    // formatting / UTF-8-checked paths), so this never fails; fall back to a fixed string
    // rather than losing the error entirely if it ever does.
    let c_message = CString::new(message)
        .unwrap_or_else(|_| CString::new("error message contained a NUL byte").unwrap());
    LAST_ERROR.with(|slot| *slot.borrow_mut() = Some(c_message));
}

/// Return codes for `cs2_parse_file`.
#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Cs2Status {
    Ok = 0,
    /// A path argument was null or not valid UTF-8.
    InvalidArgument = 1,
    /// Could not open the demo file or create/write the output file.
    Io = 2,
    /// Not a valid demo, or the demoparser2 core failed/panicked while reading it (the message
    /// from `cs2_last_error` has the detail).
    ParseFailed = 3,
    /// A panic unwound out of this function despite the inner `catch_unwind` (should not
    /// happen; kept as a last resort so the app gets an error code instead of a crash).
    InternalPanic = 4,
}

/// Progress stages reported to `progress_cb`, matching `parser_core::Stage`.
#[repr(u32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Cs2Stage {
    Events = 0,
    Players = 1,
    Grenades = 2,
    Assemble = 3,
    Done = 4,
}

impl From<Stage> for Cs2Stage {
    fn from(stage: Stage) -> Self {
        match stage {
            Stage::Events => Cs2Stage::Events,
            Stage::Players => Cs2Stage::Players,
            Stage::Grenades => Cs2Stage::Grenades,
            Stage::Assemble => Cs2Stage::Assemble,
            Stage::Done => Cs2Stage::Done,
        }
    }
}

/// `progress_cb(stage, percent, user_data)`; `user_data` is passed through unchanged (the
/// Swift side boxes an `AsyncStream` continuation in it). Called at step boundaries only, not
/// continuously — the demoparser2 core gives no hook inside a pass.
pub type Cs2ProgressCallback =
    Option<extern "C" fn(stage: u32, percent: u32, user_data: *mut c_void)>;

/// Parses the demo at `path` and writes compact gzip-compressed JSON (the format in
/// `docs/format.md`) to `out_path`, overwriting it if it exists.
///
/// Runs on the calling thread and can take tens of seconds on a full match — call it from a
/// background thread (`Task.detached` on the Swift side), never on the main thread. There is no
/// cancellation hook: once called, this runs to completion.
///
/// # Safety
/// `path` and `out_path` must be valid, NUL-terminated UTF-8 C strings for the duration of the
/// call. `user_data` is passed to `progress_cb` as-is and otherwise untouched by this function.
#[no_mangle]
pub unsafe extern "C" fn cs2_parse_file(
    path: *const c_char,
    out_path: *const c_char,
    progress_cb: Cs2ProgressCallback,
    user_data: *mut c_void,
) -> i32 {
    let result = catch_unwind(AssertUnwindSafe(|| {
        run_parse_file(path, out_path, progress_cb, user_data)
    }));

    match result {
        Ok(status) => status as i32,
        Err(payload) => {
            let msg = payload
                .downcast_ref::<&str>()
                .map(|s| s.to_string())
                .or_else(|| payload.downcast_ref::<String>().cloned())
                .unwrap_or_else(|| "unknown panic crossing the ios-bridge C boundary".into());
            set_last_error(msg);
            Cs2Status::InternalPanic as i32
        }
    }
}

unsafe fn run_parse_file(
    path: *const c_char,
    out_path: *const c_char,
    progress_cb: Cs2ProgressCallback,
    user_data: *mut c_void,
) -> Cs2Status {
    let path = match c_str_to_path(path) {
        Some(p) => p,
        None => {
            set_last_error("path is null or not valid UTF-8".into());
            return Cs2Status::InvalidArgument;
        }
    };
    let out_path = match c_str_to_path(out_path) {
        Some(p) => p,
        None => {
            set_last_error("out_path is null or not valid UTF-8".into());
            return Cs2Status::InvalidArgument;
        }
    };

    // `user_data` crosses into the callback as a bare pointer; wrapping it lets the closure
    // passed to `parse_file` be `'static`-free without `unsafe` spreading further than here.
    struct SendPtr(*mut c_void);
    unsafe impl Send for SendPtr {}
    let user_data = SendPtr(user_data);

    let mut on_progress = |p: Progress| {
        if let Some(cb) = progress_cb {
            cb(
                Cs2Stage::from(p.stage) as u32,
                p.percent as u32,
                user_data.0,
            );
        }
    };

    let parsed = parser_core::parse_file(&path, Some(&mut on_progress));
    let m = match parsed {
        Ok(m) => m,
        Err(e) => {
            set_last_error(e.to_string());
            return Cs2Status::ParseFailed;
        }
    };

    let file = match File::create(&out_path) {
        Ok(f) => f,
        Err(e) => {
            set_last_error(format!("creating {}: {e}", out_path.display()));
            return Cs2Status::Io;
        }
    };
    let encoder = GzEncoder::new(BufWriter::new(file), Compression::default());
    if let Err(e) = parser_core::write_json(&m, encoder) {
        set_last_error(e.to_string());
        return Cs2Status::Io;
    }

    Cs2Status::Ok
}

unsafe fn c_str_to_path(s: *const c_char) -> Option<std::path::PathBuf> {
    if s.is_null() {
        return None;
    }
    CStr::from_ptr(s)
        .to_str()
        .ok()
        .map(|s| Path::new(s).to_path_buf())
}

/// The last error set on the calling thread by `cs2_parse_file`, or null if none. The returned
/// string is owned by the caller and must be released with `cs2_string_free` — it is not
/// reused or freed by this crate.
#[no_mangle]
pub extern "C" fn cs2_last_error() -> *mut c_char {
    LAST_ERROR.with(|slot| match slot.borrow_mut().take() {
        Some(msg) => msg.into_raw(),
        None => std::ptr::null_mut(),
    })
}

/// Frees a string returned by `cs2_last_error`. Passing null is a no-op; passing anything else
/// is undefined behavior.
///
/// # Safety
/// `s` must be a pointer previously returned by `cs2_last_error` (and not already freed).
#[no_mangle]
pub unsafe extern "C" fn cs2_string_free(s: *mut c_char) {
    if !s.is_null() {
        drop(CString::from_raw(s));
    }
}
